public ElementMenuOptions longPressOnElement(String elementName){
  try {
    scrollTillFindElement(elementName).tap(1,1000);
  } catch (NoSuchElementException e) {
    throw new RuntimeException("Element not found: " + elementName, e);
  } catch (TimeoutException e) {
    throw new RuntimeException("Timeout while finding element: " + elementName, e);
  } catch (StaleElementReferenceException e) {
    throw new RuntimeException("Stale element reference while tapping: " + elementName, e);
  }
  ElementMenuOptions menuOptions = new ElementMenuOptions(driver);
  return menuOptions;
}
